import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { texture, uv, mix, smoothstep, mul, add, sub, vec3, vec4, float, color, luminance, saturate, contrast, brightness } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.transparent = true;
  const vUv = uv();
  const gradColor = mix(
    vec4(0, 0, 0, 0), // #0b0b1000 (transparent black)
    vec4(0, 0, 0, 0.92), // #0b0b10eb (approx 92% opacity)
    smoothstep(0.45, 1.0, vUv.y)
  );
  backdropMat.baseColorNode = gradColor;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- HERO PLATE ----------
  const plateGeom = new PlaneGeometry(4.0, 2.5, 64, 64);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.transparent = true;
  plateMat.metalness = 0.0;
  plateMat.roughness = 0.8;
  const plate = new Mesh(plateGeom, plateMat);
  root.add(plate);

  // Load textures (async, but material will update when ready)
  const imageTexPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTexPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  imageTexPromise.then(tex => {
    plateMat.map = tex;
    plateMat.needsUpdate = true;
  });

  depthTexPromise.then(depthTex => {
    // displacement node (depth map * amplitude)
    const dispNode = mul(texture(depthTex), float(0.18));
    plateMat.displacementNode = dispNode;
    plateMat.needsUpdate = true;
  });

  // Apply simple filmic grade (lift blacks, reduce highlights, desaturate, preserve red)
  // This is a lightweight approximation using nodes.
  const colorNode = texture(imageTexPromise.then(() => null) || null); // placeholder
  const lifted = add(colorNode, vec3(0.05, 0.05, 0.05)); // lift blacks
  const desat = mix(lifted, vec3(luminance(lifted)), float(0.08)); // desaturate 8%
  const contrastNode = contrast(desat, float(1.12)); // +12% contrast
  const finalColor = mix(contrastNode, vec3(1.0, 0.0, 0.0), float(0.0)); // preserve red (no change)
  plateMat.baseColorNode = finalColor;

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const { cleanup } = fn(plate, prim.params);
        primitiveCleanups.push(cleanup);
      }
    }
  }

  // ---------- CAPTION BLOCK ----------
  const captionGroup = new Group();
  // Anchor bottom‑left of the plate with 0.5 unit padding
  const padding = 0.5;
  const plateHalfW = 2.0;
  const plateHalfH = 1.25;
  captionGroup.position.set(
    -plateHalfW + padding,
    -plateHalfH + padding,
    0.01
  );
  root.add(captionGroup);

  // Text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let cursorY = 0;
  const lineGap = 0.25; // baseline rhythm

  for (const item of items) {
    const role = item.role || 'body';
    const typo = (config.typography && config.typography[role]) || {};
    const fontSize = typo.fontSize || 13;
    const colorHex = (config.colors && config.colors[role]) || config.colors?.ink || '#e8ecf2';
    const letterSpacing = typo.letterSpacing ?? 0;
    const textOpts = {
      fontSize,
      color: colorHex,
      align: 'left',
      letterSpacingPx: letterSpacing,
    };
    const txt = ctx.fontAtlas.createText(item.text, textOpts);
    txt.position.set(0, -cursorY, 0);
    captionGroup.add(txt);
    cursorY += (fontSize * (typo.lineHeight || 1.2)) / 100 + lineGap;
  }

  // Accent hairline bar between headline and body
  const barGeom = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshStandardNodeMaterial();
  barMat.emissive = new Color('#ff2a38');
  barMat.emissiveIntensity = 1.8;
  const bar = new Mesh(barGeom, barMat);
  // Position bar after the second text item (headline)
  const headlineIdx = items.findIndex(i => i.role === 'headline');
  if (headlineIdx >= 0) {
    const headlineItem = items[headlineIdx];
    const typo = (config.typography && config.typography.headline) || {};
    const headlineHeight = (typo.fontSize || 34) * (typo.lineHeight || 1.1) / 100;
    bar.position.set(0, -(headlineHeight + lineGap + 0.01), 0);
    captionGroup.add(bar);
  }

  // ---------- ANIMATION ----------
  const timelines = [];

  // Plate fade‑in
  const plateTL = gsap.timeline();
  plateTL.fromTo(
    plateMat,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  timelines.push(plateTL);

  // Caption rise‑in
  const captionTL = gsap.timeline({ delay: 0.12 });
  captionTL.fromTo(
    captionGroup.position,
    { y: captionGroup.position.y + 0.4 },
    { y: captionGroup.position.y, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }
  );
  timelines.push(captionTL);

  // ---------- USERDATA ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    plateGeom.dispose();
    plateMat.dispose();
    barGeom.dispose();
    barMat.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Primitive cleanups
    for (const clean of primitiveCleanups) clean();

    // Remove children
    root.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return root;
}
